<?php
require_once __DIR__.'/../core/JalaliDate.php';
require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Database.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../core/HrModule.php';Auth::requirePermission('hr_kpi.results');$pageTitle='نتایج ارزیابی KPI';$user=Auth::user();$ids=HrModule::accessibleEmployeeIds($user);if(!$ids)$ids=[-1];$where=['s.employee_id IN ('.implode(',',array_fill(0,count($ids),'?')).')'];$params=$ids;
$filters=['employee_id'=>'s.employee_id','period_id'=>'s.period_id','template_id'=>'s.template_id'];foreach($filters as $key=>$column){$v=(int)($_GET[$key]??0);if($v){$where[]="$column=?";$params[]=$v;}}
foreach(['department'=>'u.department','role_key'=>'u.role_key','sales_line'=>'u.sales_line'] as $key=>$column){$v=trim($_GET[$key]??'');if($v!==''){$where[]="$column=?";$params[]=$v;}}
foreach(['supervisor_id'=>'u.supervisor_id','manager_id'=>'u.organization_manager_id'] as $key=>$column){$v=(int)($_GET[$key]??0);if($v){$where[]="$column=?";$params[]=$v;}}if(trim($_GET['from_date']??'')!==''){$where[]='DATE(s.scored_at)>=?';$params[]=JalaliDate::toGregorian($_GET['from_date'])?:$_GET['from_date'];}if(trim($_GET['to_date']??'')!==''){$where[]='DATE(s.scored_at)<=?';$params[]=JalaliDate::toGregorian($_GET['to_date'])?:$_GET['to_date'];}
$sql='SELECT u.id employee_id,u.name,u.department,u.role_key,u.sales_line,t.title template_title,t.id template_id,p.title period_title,p.id period_id,ROUND(SUM(s.score*c.weight)/NULLIF(SUM(c.max_score*c.weight),0)*100,2) average_score,SUM(s.score*c.weight) total_score,GROUP_CONCAT(CONCAT(c.criteria_text,": ",s.score,"/",c.max_score) SEPARATOR " | ") criteria_scores,GROUP_CONCAT(NULLIF(s.notes,"") SEPARATOR " | ") notes,MAX(s.scored_at) scored_at,MAX(sc.name) scored_by FROM hr_kpi_scores s JOIN users u ON u.id=s.employee_id JOIN hr_kpi_templates t ON t.id=s.template_id JOIN hr_kpi_periods p ON p.id=s.period_id JOIN hr_kpi_criteria c ON c.id=s.criteria_id LEFT JOIN users sc ON sc.id=s.scored_by WHERE '.implode(' AND ',$where).' GROUP BY u.id,t.id,p.id ORDER BY p.sort_order DESC,average_score DESC';$results=Database::fetchAll($sql,$params);
if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="hr-kpi-results.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['نام','واحد','نقش','لاین','قالب','دوره','امتیاز کل','میانگین','امتیاز معیارها','یادداشت','امتیازدهنده','زمان']);foreach($results as $r)fputcsv($out,[$r['name'],$r['department'],$r['role_key'],$r['sales_line'],$r['template_title'],$r['period_title'],$r['total_score'],$r['average_score'],$r['criteria_scores'],$r['notes'],$r['scored_by'],$r['scored_at']]);fclose($out);exit;}
$employees=Database::fetchAll('SELECT id,name FROM users WHERE id IN ('.implode(',',array_fill(0,count($ids),'?')).') ORDER BY name',$ids);$templates=Database::fetchAll('SELECT id,title FROM hr_kpi_templates ORDER BY title');$periods=Database::fetchAll('SELECT id,title FROM hr_kpi_periods ORDER BY sort_order');require __DIR__.'/../views/partials/admin-header.php';?>
<form class="card admin-form" method="get"><h2>فیلتر نتایج</h2><div class="grid grid-3"><label class="form-field"><span>پرسنل</span><select name="employee_id"><option value="">همه</option><?php foreach($employees as $e):?><option value="<?=$e['id']?>" <?=(int)($_GET['employee_id']??0)===(int)$e['id']?'selected':''?>><?=e($e['name'])?></option><?php endforeach?></select></label><label class="form-field"><span>قالب</span><select name="template_id"><option value="">همه</option><?php foreach($templates as $t):?><option value="<?=$t['id']?>" <?=(int)($_GET['template_id']??0)===(int)$t['id']?'selected':''?>><?=e($t['title'])?></option><?php endforeach?></select></label><label class="form-field"><span>دوره</span><select name="period_id"><option value="">همه</option><?php foreach($periods as $p):?><option value="<?=$p['id']?>" <?=(int)($_GET['period_id']??0)===(int)$p['id']?'selected':''?>><?=e($p['title'])?></option><?php endforeach?></select></label><label class="form-field"><span>واحد</span><input name="department" value="<?=e($_GET['department']??'')?>"></label><label class="form-field"><span>نقش</span><input name="role_key" value="<?=e($_GET['role_key']??'')?>"></label><label class="form-field"><span>لاین فروش</span><input name="sales_line" value="<?=e($_GET['sales_line']??'')?>"></label></div><div class="form-actions"><button class="btn btn-primary">اعمال فیلتر</button><button class="btn" name="export" value="csv">خروجی CSV</button></div></form>
<form class="card admin-form" method="get"><h2>فیلتر مسئول و بازه زمانی</h2><?php foreach(['employee_id','template_id','period_id','department','role_key','sales_line'] as $key):if(($_GET[$key]??'')!==''):?><input type="hidden" name="<?=e($key)?>" value="<?=e($_GET[$key])?>"><?php endif;endforeach?><div class="grid grid-3"><label class="form-field"><span>شناسه سرپرست</span><input type="number" min="1" name="supervisor_id" value="<?=e($_GET['supervisor_id']??'')?>"></label><label class="form-field"><span>شناسه مدیر</span><input type="number" min="1" name="manager_id" value="<?=e($_GET['manager_id']??'')?>"></label><label class="form-field"><span>از تاریخ</span><input class="jalali-date-input" name="from_date" value="<?=e($_GET['from_date']??'')?>"></label><label class="form-field"><span>تا تاریخ</span><input class="jalali-date-input" name="to_date" value="<?=e($_GET['to_date']??'')?>"></label></div><button class="btn btn-primary">اعمال فیلتر تکمیلی</button></form>
<section class="card"><div class="table-wrap"><table><thead><tr><th>پرسنل</th><th>واحد / نقش</th><th>قالب</th><th>دوره</th><th>میانگین</th><th>روند</th><th>جزئیات</th></tr></thead><tbody><?php foreach($results as $r):?><tr><td><?=e($r['name'])?></td><td><?=e(($r['department']?:'-').' / '.($r['role_key']?:'-'))?></td><td><?=e($r['template_title'])?></td><td><?=e($r['period_title'])?></td><td><span class="achievement-pill <?=((float)$r['average_score']>=75?'achievement-good':((float)$r['average_score']>=60?'achievement-warn':'achievement-bad'))?>"><?=e($r['average_score'])?>٪</span></td><td><?=e((float)$r['average_score']>=75?'خوب':((float)$r['average_score']>=60?'پایدار':'نیازمند پیگیری'))?></td><td><details><summary>مشاهده</summary><p><?=e($r['criteria_scores'])?></p><?php if($r['notes']):?><p class="muted"><?=e($r['notes'])?></p><?php endif?></details></td></tr><?php endforeach?><?php if(!$results):?><tr><td colspan="7">نتیجه‌ای یافت نشد.</td></tr><?php endif?></tbody></table></div></section>
</section></main></div><script src="/assets/js/app.js"></script></body></html>
